<?php require 'header.php'; $db=db_load(); if($_SERVER['REQUEST_METHOD']==='POST'){foreach(['clinic_name','tagline','doctor_name','qualification','phone','email','address','hero_title','hero_text','primary_color','light_color','medium_color','admin_user','admin_password'] as $k)$db['settings'][$k]=trim(post($k));db_save($db);$saved=true;} $s=$db['settings']; ?><div class="admin-top"><h1>Website Settings</h1></div><?php if(!empty($saved)): ?><div class="notice">Settings saved successfully.</div><?php endif; ?><div class="form-card"><form method="post"><div class="form-grid"><?php foreach(['clinic_name'=>'Clinic Name','tagline'=>'Tagline','doctor_name'=>'Doctor Name','qualification'=>'Qualification','phone'=>'Phone','email'=>'Email','address'=>'Address','hero_title'=>'Hero Title','hero_text'=>'Hero Text','primary_color'=>'Dark Green / Primary Color','light_color'=>'Light Green Color','medium_color'=>'Medium Green Color','admin_user'=>'Admin Username','admin_password'=>'Admin Password'] as $k=>$label): ?><div class="field <?=$k==='address'||$k==='hero_title'||$k==='hero_text'?'full':''?>"><label><?=e($label)?></label><input name="<?=e($k)?>" value="<?=e($s[$k])?>"></div><?php endforeach; ?><div class="field full"><button class="btn">Save Settings</button></div></div></form></div><?php require 'footer.php'; ?>
